"""Update the figure with the newly completed same-epoch4 native Stem pair."""
from pathlib import Path
import base64,copy,hashlib,json
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'outputs/stem_curves_20261011_v1';MAIN=ROOT/'outputs/stem_component12_20261011_v1';REF=ROOT/'outputs/native_stem_scratch12_20261011_v3'
read=lambda p:json.loads(Path(p).read_bytes());sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
def write(p,v):
    with Path(p).open('x',encoding='utf8') as f:json.dump(v,f,ensure_ascii=False,indent=2,allow_nan=False)
assert read(OUT/'render_verification_v1.json')['all_points_exact_to_source_data']
old=read(OUT/'plot_data_v1.json');assert sha(OUT/'plot_data_v1.json')==read(OUT/'rendered/plot_report.json')['data_sha256']
snapshot=read(MAIN/'training_observation_v24.json');assert sha(MAIN/'training_observation_v24.json')==read(MAIN/'training_observation_v24_transport_verification.json')['verified_snapshot_sha256']
payloads=json.loads("{\"1\":{\"base64\":\"\",\"expected_sha256\":\"7d3b999f9415655324cc39362b8e142e4c093364a68a2bd3b4d513fb37ef67a5\",\"expected_bytes\":3042},\"2\":{\"base64\":\"\",\"expected_sha256\":\"6275740b82a82f9a8c9c7b5852dee1f2a06d3d32902dcb7bd8d3c0fbd67a3c04\",\"expected_bytes\":3043}}");observations={};transport={}
for seed in (1,2):
    d=payloads[str(seed)];b=base64.b64decode(d['base64'],validate=True)
    assert len(b)==d['expected_bytes'] and hashlib.sha256(b).hexdigest()==d['expected_sha256']
    name=f'compact_payload_seed{seed}_v8.json'
    with (REF/name).open('xb') as f:f.write(b)
    o=json.loads(b);assert o['seed']==seed and o['code_sha256_verified'] and not o['failures']
    assert o['completed_epochs']==4 and o['latest_metrics']['epoch']==3
    assert all(p['same_live'] for p in o['processes'].values())
    observations[str(seed)]=o;transport[str(seed)]={k:v for k,v in d.items() if k!='base64'};transport[str(seed)]['file']=name
write(REF/'compact_transport_v8.json',transport);write(REF/'compact_observation_v8.json',observations)
pairs=[]
for seed in (1,2):
    ref=observations[str(seed)]['latest_metrics']['test_coco_eval_bbox']
    full=snapshot[f'seed{seed}']['jobs']['original_stem']['metrics'][3]['test_coco_eval_bbox']
    pairs.append(dict(seed=seed,epoch=4,enhanced_AP=100*full[0],random_native_AP=100*ref[0],delta_AP_pp=100*(full[0]-ref[0]),
        enhanced_APs=100*full[3],random_native_APs=100*ref[3],delta_APs_pp=100*(full[3]-ref[3])))
write(MAIN/'same_epoch_random_native_comparison_v5.json',dict(status='ANALYZED_DESCRIPTIVE_SAME_EPOCH4_BOTH_SEEDS',
    current_S_pairs=pairs,full_snapshot_sha256=sha(MAIN/'training_observation_v24.json'),random_native_observation_sha256=sha(REF/'compact_observation_v8.json'),
    all_seeds_preserved=True,fixed12_efficacy_established=False,root_cause_established=False,
    interpretation='At epoch4 both arms share the comparison endpoint within each seed. Enhanced is positive on seed2 and negative on seed1. Fixed12 saved-EMA result is pending.',
    new_model_forwards=0,new_optimizer_updates=0))
data=copy.deepcopy(old);data['rows']=[r for r in data['rows'] if r['arm']=='pretrained_BASE']
for seed in (1,2):
    o=snapshot[f'seed{seed}'];ref=observations[str(seed)]
    for arm in ('original_stem','detail_lowres','highfreq_rgb'):
        assert all(p['same_live'] for p in o['jobs'][arm]['processes'])
        for r in o['jobs'][arm]['metrics']:
            v=r['test_coco_eval_bbox'];data['rows'].append(dict(seed=seed,arm=arm,epoch=r['epoch']+1,AP=100*v[0],APs=100*v[3]))
    history=read(OUT/f'reference_history_seed{seed}_v1.json')['rows']
    assert sha(OUT/f'reference_history_seed{seed}_v1.json')==old['sources'][str(seed)]['reference_payload_sha256']
    history=[r for r in history if r['epoch']<3]+[dict(epoch=3,test_coco_eval_bbox=ref['latest_metrics']['test_coco_eval_bbox'])]
    assert [r['epoch'] for r in history]==list(range(4))
    for r in history:
        v=r['test_coco_eval_bbox'];data['rows'].append(dict(seed=seed,arm='native_stem_scratch',epoch=r['epoch']+1,AP=100*v[0],APs=100*v[3]))
    data['sources'][str(seed)].update(full_and_controls_remote_UTC=o['observed_remote_UTC'],reference_remote_UTC=ref['observed_remote_UTC'],
        reference_latest_epoch_payload_sha256=transport[str(seed)]['expected_sha256'],reference_latest_epoch_payload_file=str(REF/transport[str(seed)]['file']),
        completed_epochs={a:len(o['jobs'][a]['metrics']) for a in ('original_stem','detail_lowres','highfreq_rgb')}|{'pretrained_BASE':12,'native_stem_scratch':4})
assert len(data['rows'])==87
data['snapshot_sha256']=sha(MAIN/'training_observation_v24.json')
write(OUT/'plot_data_v2.json',data)
print(json.dumps(dict(data_base64=base64.b64encode((OUT/'plot_data_v2.json').read_bytes()).decode(),data_sha256=sha(OUT/'plot_data_v2.json'),
    plot_code_sha256=sha(ROOT/'英文小论文/code/stem_curves_20261011_v1/plot.py'),pairs=pairs),ensure_ascii=False))

